const text = $json.text || $json.content || $json.input;
if (!text) throw new Error('Missing text/content/input field');
return [{ json: { text } }];

const original = $json.text;
const humanized = $json.text;

// Calculate improvement metrics
const aiPhrases = [
  'in today\'s digital landscape', 'it is important to note that',
  'furthermore', 'moreover', 'additionally', 'utilize', 'leverage',
  'endeavor', 'facilitate', 'robust', 'seamless', 'unleash',
  'delve', 'transformative', 'game-changer', 'i hope this email'
];

const originalLower = original.toLowerCase();
const humanizedLower = humanized.toLowerCase();

let aiCountBefore = 0;
let aiCountAfter = 0;
aiPhrases.forEach(phrase => {
  const regex = new RegExp(phrase.replace(/\./g, '\\.'), 'gi');
  aiCountBefore += (originalLower.match(regex) || []).length;
  aiCountAfter += (humanizedLower.match(regex) || []).length;
});

return [{
  json: {
    original,
    humanized,
    metrics: {
      ai_phrases_before: aiCountBefore,
      ai_phrases_after: aiCountAfter,
      reduction_pct: aiCountBefore > 0 ? Math.round((1 - aiCountAfter/aiCountBefore) * 100) : 0,
      chars_original: original.length,
      chars_humanized: humanized.length
    },
    processed_at: new Date().toISOString()
  }
}];
